// Même vérification que auto-evenements : HMAC-SHA256 du corps re-sérialisé, seuls les événements relance.a_envoyer passent.
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
return $input.all().map((item) => {
  const corps = JSON.stringify(item.json.body);
  const attendu = 'sha256=' + crypto.createHmac('sha256', secret).update(corps).digest('hex');
  const recu = String(item.json.headers['x-auto-signature'] ?? '');
  if (recu.length !== attendu.length || !crypto.timingSafeEqual(Buffer.from(recu), Buffer.from(attendu))) {
    throw new Error('signature invalide');
  }
  if (item.json.body.type !== 'relance.a_envoyer') throw new Error('événement inattendu : ' + item.json.body.type);
  return { json: item.json.body };
});

// Livraison au moins une fois : un événement déjà vu (même id) n'envoie pas un second mail.
// Données statiques conservées entre exécutions du workflow publié ; purge après 30 jours.
const vus = $getWorkflowStaticData('global');
vus.ids = vus.ids ?? {};
const limite = Date.now() - 30 * 86400000;
for (const [id, t] of Object.entries(vus.ids)) if (t < limite) delete vus.ids[id];
const nouveaux = [];
for (const item of $input.all()) {
  if (vus.ids[item.json.id]) continue;
  vus.ids[item.json.id] = Date.now();
  nouveaux.push(item);
}
return nouveaux;

// Objet et texte selon le palier (J+7, J+30, J+60) ; sans adresse du client, rien n'est envoyé.
// Relance déjà envoyée par auto depuis la boîte de l'entreprise (envoyeParMail) : rien à faire ici.
const OBJETS = {
  1: (n) => `Rappel : facture ${n} échue`,
  2: (n) => `Deuxième relance : facture ${n} impayée`,
  3: (n) => `Mise en demeure : facture ${n}`,
};
const euros = (c) => (c / 100).toLocaleString('fr-FR', { style: 'currency', currency: 'EUR' });
return $input.all()
  .filter((item) => item.json.data?.client?.email && !item.json.data?.envoyeParMail)
  .map((item) => {
    const d = item.json.data;
    return {
      json: {
        evenementId: item.json.id,
        tenantId: item.json.tenantId,
        documentId: d.documentId,
        niveau: d.niveau,
        a: d.client.email,
        objet: OBJETS[d.niveau](d.numero),
        texte:
          `Bonjour,\n\nSauf erreur de notre part, la facture ${d.numero} arrivée à échéance le ${d.echeance} ` +
          `reste impayée : ${euros(d.resteCents)} (${d.joursRetard} jours de retard).\n` +
          `Merci de procéder à son règlement dans les meilleurs délais.\n\nCordialement`,
      },
    };
  });
